		int amount = hit.getAmount();
		if (amount == 0) return;
		if (hit.getHitsplatType() != HitsplatID.DAMAGE_ME) return;
		if (healsplats.isEmpty()) return;
		int heals = healsplats.get(healsplats.size()-1).getAmount();
